#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    long long A, B;
} Line;

static int cmpLine(const void *pa, const void *pb) {
    const Line *a = (const Line *)pa;
    const Line *b = (const Line *)pb;
    if (a->A < b->A) return -1;
    if (a->A > b->A) return 1;
    if (a->B < b->B) return -1;
    if (a->B > b->B) return 1;
    return 0;
}

static int cmpLL(const void *pa, const void *pb) {
    long long a = *(const long long *)pa;
    long long b = *(const long long *)pb;
    return (a > b) - (a < b);
}

static int lower_bound_ll(const long long *arr, int n, long long val) {
    int l = 0, r = n;
    while (l < r) {
        int mid = (l + r) / 2;
        if (arr[mid] < val) l = mid + 1;
        else r = mid;
    }
    return l;
}

static int upper_bound_ll(const long long *arr, int n, long long val) {
    int l = 0, r = n;
    while (l < r) {
        int mid = (l + r) / 2;
        if (arr[mid] <= val) l = mid + 1;
        else r = mid;
    }
    return l;
}

static long long countThreshold(Line *lines, int n, long long T, int strict) {
    long long *v = (long long *)malloc(sizeof(long long) * n);
    long long *vals = (long long *)malloc(sizeof(long long) * n);

    for (int i = 0; i < n; i++) {
        v[i] = lines[i].A * T + lines[i].B;
    }

    memcpy(vals, v, sizeof(long long) * n);
    qsort(vals, n, sizeof(long long), cmpLL);

    int m = 0;
    for (int i = 0; i < n; i++) {
        if (i == 0 || vals[i] != vals[m - 1]) {
            vals[m++] = vals[i];
        }
    }

    int *bit = (int *)calloc(m + 1, sizeof(int));
    long long ans = 0;

    int i = 0;
    while (i < n) {
        int j = i + 1;
        while (j < n && lines[j].A == lines[i].A) j++;

        for (int k = i; k < j; k++) {
            int idx;
            if (strict) {
                idx = lower_bound_ll(vals, m, v[k]);
            } else {
                idx = upper_bound_ll(vals, m, v[k]);
            }

            int sum = 0;
            for (int p = idx; p > 0; p -= p & -p) {
                sum += bit[p];
            }
            ans += sum;
        }

        for (int k = i; k < j; k++) {
            int idx = lower_bound_ll(vals, m, v[k]) + 1;
            for (int p = idx; p <= m; p += p & -p) {
                bit[p]++;
            }
        }

        i = j;
    }

    free(v);
    free(vals);
    free(bit);
    return ans;
}

int main(void) {
    int N;
    long long X1, X2;

    if (scanf("%d %lld %lld", &N, &X1, &X2) != 3) return 0;

    Line *lines = (Line *)malloc(sizeof(Line) * N);
    for (int i = 0; i < N; i++) {
        scanf("%lld %lld", &lines[i].A, &lines[i].B);
    }

    qsort(lines, N, sizeof(Line), cmpLine);

    long long ans = countThreshold(lines, N, X2, 0)
                  - countThreshold(lines, N, X1, 1);

    printf("%lld\n", ans);

    free(lines);
    return 0;
}
